contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount, uint256 priorAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (priorAmount) + (amount)); require(priorAmount <= 1000000000000000000000000000000); require(amount <= 1000000000000000000000000000000);
        require(amount <= 10**18);
        require(priorAmount <= 10**18);
        require(address(this).balance >= priorAmount + amount);

        uint256 preBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;

        c.Deposit{value: priorAmount}(); if (__ESBMC_reverted()) return;
        c.Deposit{value: amount}(); if (__ESBMC_reverted()) return;

        uint256 expectedAfterFirst = preBalance + priorAmount;
        uint256 expectedFinal = expectedAfterFirst + amount;

        assert(c.balances(address(this)) == expectedFinal);
    }

    receive() external payable {}
}

