// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 amount, uint256 priorAmount) internal {
        priorAmount = bound(priorAmount, 0, 1000000000000000000000000000000);
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount <= 10**18);
        vm.assume(priorAmount <= 10**18);
        vm.assume(address(this).balance >= priorAmount + amount);
        uint256 preBalance;
        try c.balances(address(this)) returns (uint256 __r) { preBalance = __r; } catch { return; }
        try c.Deposit{value: priorAmount}() {} catch { return; }
        try c.Deposit{value: amount}() {} catch { return; }
        uint256 expectedAfterFirst = preBalance + priorAmount;
        uint256 expectedFinal = expectedAfterFirst + amount;
        assertTrue(c.balances(address(this)) == expectedFinal);
    }

    function testFuzz_run(uint256 amount, uint256 priorAmount) public {
        _run(amount, priorAmount);
    }

    receive() external payable {}
}
